#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzTexture(int tex,float2 uv) { return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_BPM;
uniform float amzp_STEPS;
uniform float amzp_EPS;
uniform float amzp_MAX_DIST;
uniform float amzp_SPIN_SCALE;
float2 rot2(float2 a, float b){
    float c = cos(b), s = sin(b);
    return float2(a.x*c - a.y*s, a.x*s + a.y*c);
}
float sdBox(float3 p, float3 r){
    float3 d = abs(p) - r;
    return min(max(d.x, max(d.y, d.z)), 0.0) + length(max(d, 0.0));
}
float sdRoundBox(float3 p, float3 r, float rr){
    return sdBox(p, r - float3(rr)) - rr;
}
float tick(float t){
    t = smoothstep(0.0, 1.0, t);
    t = smoothstep(0.0, 1.0, t);
    return t;
}
float noise1(float a){
    return fract(a * 123.4762831);
}
float hash2(float2 a){
    return fract(sin(dot(a, float2(4.43243, 12.4762)) * 13.43762));
}
float2 splitScene(float3 p, float spinScale, float SPEED){
    float amzLocal_time = time * SPEED;
    float t = tick(fract(amzLocal_time));
    float mode = noise1(floor(amzLocal_time)) * 3.0;
    float axisDirection = (fract(mode) < 0.5) ? -1.0 : 1.0;
    float spinDirection = (mod(mode, 0.5) < 0.25) ? -1.0 : 1.0;
    t *= spinDirection;
    float clipDist = 0.0;
    if (mode < 1.0){
        p.yz = rot2(p.yz, t * (3.14159265359*0.5) * spinScale);
        clipDist = p.x * axisDirection - 0.5;
    } else if (mode < 2.0){
        p.xz = rot2(p.xz, t * (3.14159265359*0.5) * spinScale);
        clipDist = p.y * axisDirection - 0.5;
    } else {
        p.xy = rot2(p.xy, t * (3.14159265359*0.5) * spinScale);
        clipDist = p.z * axisDirection - 0.5;
    }
    clipDist *= (1.0 - spinScale * 2.0);
    float3 lp = mod(p + 0.5, 1.0) - 0.5;
    float distCubes = max(
        sdBox(p, float3(1.5)),
        sdRoundBox(lp, float3(0.48), 0.04)
    );
    float3 stickerSize = float3(0.4, 0.4, 1.0);
    float stickerRadius = 0.05;
    float distStickers = min(
        min(
            sdRoundBox(lp, stickerSize.xyz, stickerRadius),
            sdRoundBox(lp, stickerSize.yzx, stickerRadius)
        ),
        sdRoundBox(lp, stickerSize.zxy, stickerRadius)
    );
    distStickers = max(distStickers, -sdBox(p, float3(1.4)));
    distCubes = max(distCubes, clipDist);
    float color = 0.0;
    color += floor(p.x + 1.5) * 3.0;
    color += floor(p.y + 1.5) * 7.0;
    color += floor(p.z + 1.5) * 11.0;
    color += mode;
    return float2(distCubes, (distStickers < 0.0) ? (1.0 + color) : 0.0);
}
float2 sceneSDF(float3 p, float SPEED){
    float2 a = splitScene(p, 0.0, SPEED);
    float2 b = splitScene(p, amzp_SPIN_SCALE, SPEED);
    return (a.x < b.x) ? float2(a.x, a.y) : float2(b.x, b.y);
}
float3 colorForIndex(int idx){
    if (idx == 0) return float3(1.0, 0.0, 0.0);
    if (idx == 1) return float3(1.0, 1.0, 0.0);
    if (idx == 2) return float3(0.0, 1.0, 0.0);
    if (idx == 3) return float3(1.0, 1.0, 1.0);
    if (idx == 4) return float3(0.0, 0.0, 1.0);
    return float3(1.0, 0.5, 0.0);
}
void amzRender(){
    float2 R = screen.zw;
    float2 uv = amzScreenNorm() - 0.5;
    uv.x *= R.x / max(R.y, 1.0);
    float SPEED = max(amzp_BPM, 1.0) / 60.0;
    float3 cam = float3(0.0, 0.0, -10.0);
    float3 dir = normalize(float3(uv, 1.5));
    float angYZ = sin(time) * 0.3 + 0.3;
    cam.yz = rot2(cam.yz, angYZ);
    dir.yz = rot2(dir.yz, angYZ);
    float angXZ = time * 0.5;
    cam.xz = rot2(cam.xz, angXZ);
    dir.xz = rot2(dir.xz, angXZ);
    float t = 0.0;
    float2 k = float2(0.0);
    int maxSteps = int(clamp(amzp_STEPS, 1.0, 200.0));
    const int MAX_IT = 200;
    for (int i = 0; i < MAX_IT; ++i){
        if (i >= maxSteps) break;
        k = sceneSDF(cam + dir * t, SPEED);
        t += k.x;
        if (k.x < amzp_EPS) break;
        if (t > amzp_MAX_DIST){
            k.y = -1.0;
            break;
        }
    }
    float3 h = cam + dir * t;
    float2 o = float2(0.001, 0.0);
    float3 n = normalize(float3(
        sceneSDF(h + float3(o.x, o.y, o.y), SPEED).x - sceneSDF(h - float3(o.x, o.y, o.y), SPEED).x,
        sceneSDF(h + float3(o.y, o.x, o.y), SPEED).x - sceneSDF(h - float3(o.y, o.x, o.y), SPEED).x,
        sceneSDF(h + float3(o.y, o.y, o.x), SPEED).x - sceneSDF(h - float3(o.y, o.y, o.x), SPEED).x
    ));
    float mat = k.y;
    float3 outc;
    if (abs(mat) < 1e-6){
        float fresnel = pow(1.0 - dot(-dir, n), 5.0);
        fresnel = mix(0.0016, 0.1, fresnel);
        outc = float3(fresnel);
    } else if (mat < -0.5){
        float2 luv = uv * (1.0 - length(uv) * 0.2);
        float2 c = floor(luv * 10.0 + time);
        float2 u = fract(luv * 10.0 + time) - 0.5;
        int colorIndex = int(floor(hash2(c + 0.1 * floor(time * SPEED)) * 6.0 + 1e-4));
        colorIndex = amzIntClamp(colorIndex, 0, 5);
        float d = sdRoundBox(float3(u, 0.0), float3(0.46), 0.05);
        float mask = smoothstep(0.0, 0.01, -d);
        float vignette = smoothstep(1.0, 0.3, length(luv)) * 0.7;
        outc = colorForIndex(colorIndex) * mask * vignette;
    } else {
        float m = mod(mat, 6.0);
        m += (step(0.1, n.x) + 0.0) * float(abs(n.x) > 0.1);
        m += (step(0.1, n.y) + 2.0) * float(abs(n.y) > 0.1);
        m += (step(0.1, n.z) + 4.0) * float(abs(n.z) > 0.1);
        int idx = int(mod(m, 6.0));
        outc = colorForIndex(idx);
    }
    outc = pow(max(outc, 0.0), float3(0.4545));
    outc = pow(outc, float3(1.2, 1.1, 1.0));
    amzOutput = float4(outc, 1.0);
}

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

